.first.nav__item .nav__link::after {
    background-image: url(../img/icons/icons.svg#file-filled);
}

.nav__link {
    display: block;
    padding-left: 32px;
    position: relative;
    font-weight: 400;
    -webkit-transition: .25s ease;
    transition: .25s ease;
}

.nav__link:focus,.nav__link:hover {
    color: #e47d18;
}

.nav__link:focus::after,.nav__link:hover::after {
    -webkit-filter: invert(51%) sepia(96%) saturate(1365%) hue-rotate(355deg) brightness(95%) contrast(87%);
    filter: invert(51%) sepia(96%) saturate(1365%) hue-rotate(355deg) brightness(95%) contrast(87%);
}

.nav__link:focus .nav__icon::after,.nav__link:hover .nav__icon::after {
    -webkit-filter: invert(51%) sepia(96%) saturate(1365%) hue-rotate(355deg) brightness(95%) contrast(87%);
    filter: invert(51%) sepia(96%) saturate(1365%) hue-rotate(355deg) brightness(95%) contrast(87%);
}

.nav__link::after {
    content: "";
    position: absolute;
    left: 0;
    top: 50%;
    -webkit-transform: translateY(-50%);
    transform: translateY(-50%);
    height: 24px;
    width: 24px;
    -webkit-transition: .25s ease;
    transition: .25s ease;
    -webkit-filter: invert(0) sepia(3%) saturate(5340%) hue-rotate(358deg) brightness(90%) contrast(75%);
    filter: invert(0) sepia(3%) saturate(5340%) hue-rotate(358deg) brightness(90%) contrast(75%);
    background-repeat: no-repeat;
    background-position: center;
    background-size: cover;
}

