    gap: 18px;
    color: #1c1c1c;
    text-decoration: none;
}

.open-day-page__link:nth-child(1) {
    grid-column: 1;
    grid-row: 1;
}

.open-day-page__link:nth-child(2) {
    grid-column: 1;
    grid-row: 2;
}

.open-day-page__link:nth-child(3) {
    grid-column: 2;
    grid-row: 1;
}

.open-day-page__link:nth-child(4) {
    grid-column: 2;
    grid-row: 2;
}

.open-day-page__link-icon {
    width: 58px;
    height: 58px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.open-day-page__link-icon img {
    max-width: 52px;
    max-height: 52px;
    display: block;
}

.open-day-page__link-text {
    min-height: 66px;
    padding: 0 24px;
    display: flex;
    align-items: center;
    background: #fff;
    border-radius: 6px;
    color: #202020;
    font-size: 24px;
    font-weight: 400;
    line-height: 1.2;
    text-align: left;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.open-day-page__link:hover .open-day-page__link-text {
    transform: translateY(-2px);
    box-shadow: 0 10px 28px rgba(49, 56, 73, 0.08);
}

/* Правки под clean_header / clean_footer */
.open-day-page-body .header {
    display: none;
}

.open-day-page-body .footer {
    background: #fff;
}

.open-day-page-body .footer__logo {
    display: none;
}

.open-day-page-body .footer__container {
    max-width: 920px;
}

.open-day-page-body .footer__bottom {
    color: #4a4a4a;
    text-align: center;
    font-size: 12px;
    line-height: 1.45;
    letter-spacing: 0.04em;
}

.open-day-page-body .footer__bottom a {
    color: inherit;
    text-decoration: none;
}

/* Мобильная версия */
@media (max-width: 767px) {
    .open-day-page {
        min-height: auto;
        padding: 32px 25px 72px;
    }

    .open-day-page__top {
        align-items: center;
    }

    .open-day-page__logo img {
        width: 152px;
    }

    .open-day-page__phone {
        font-size: 14px;
        gap: 8px;
    }

    .open-day-page__phone-icon {
        width: 12px;
        height: 18px;
    }

    .open-day-page__content {
        max-width: 430px;
        padding-top: 76px;
    }

    .open-day-page__title {
        font-size: 24px;
        line-height: 1.22;
        letter-spacing: 0.06em;
    }

    .open-day-page__code {
        margin-top: 24px;
        font-size: 24px;
        line-height: 1.2;
        letter-spacing: 0.05em;
