/* ================================
   Новая форма заявки Cursor
   ================================ */

.cursor-lead-form {
  width: min(860px, calc(100% - 32px));
  margin: 42px auto 0;
  padding: 38px;
  border-radius: 34px;
  background:
    radial-gradient(circle at 90% 0%, rgba(211, 117, 24, 0.16), transparent 34%),
    rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.16);
  box-shadow: 0 28px 70px rgba(0, 0, 0, 0.22);
}

/* Поля имя + телефон */
.cursor-lead-form__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 22px;
  margin-bottom: 24px;
}

.cursor-lead-form__field {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.cursor-lead-form__field label {
  color: #ffffff;
  font-size: 15px;
  font-weight: 900;
  line-height: 1.2;
}

.cursor-lead-form__field input {
  width: 100%;
  height: 64px;
  padding: 0 22px;
  border-radius: 20px;
  border: 2px solid transparent;
  background: #ffffff;
  color: #313849;
  font-size: 17px;
  font-weight: 800;
  outline: none;
  box-shadow: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
}

.cursor-lead-form__field input::placeholder {
  color: rgba(49, 56, 73, 0.55);
}

.cursor-lead-form__field input:focus {
  border-color: #d37518;
  box-shadow: 0 0 0 5px rgba(211, 117, 24, 0.18);
  transform: translateY(-1px);
}

/* Ошибки */
.cursor-lead-form__error,
.cursor-lead-form__error-main {
  color: #ffb3a7;
  font-size: 13px;
  font-weight: 800;
  line-height: 1.35;
}

.cursor-lead-form__error:empty {
  display: none;
}

/* Капча — убираем огромную серую плашку */
.cursor-lead-form__captcha {
  width: fit-content;
  max-width: 100%;
  margin: 6px auto 24px;
  padding: 14px;
  display: flex;
  justify-content: center;
  align-items: center;
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.10);
  border: 1px solid rgba(255, 255, 255, 0.12);
  overflow: hidden;
}

.cursor-lead-form__captcha > div {
  max-width: 100%;
}

/* Согласие */
.cursor-lead-form__agree {
  max-width: 760px;
  margin: 0 auto 26px;
  padding: 16px 18px;
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  gap: 13px;
  align-items: start;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.86);
  font-size: 15px;
  line-height: 1.5;
  cursor: pointer;
}

.cursor-lead-form__agree input {
  width: 19px;
  height: 19px;
  margin: 2px 0 0;
  accent-color: #d37518;
}

.cursor-lead-form__agree span {
  display: block;
}

.cursor-lead-form__agree a {
  color: #ffbd76;
  font-weight: 900;
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* Кнопка — делаем не огромной на всю ширину */
.cursor-lead-form__submit {
  width: min(420px, 100%);
  min-height: 62px;
  margin: 0 auto;
  padding: 18px 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 999px;
  background: linear-gradient(135deg, #d37518, #ffa648);
  color: #ffffff;
  font-size: 16px;
  font-weight: 950;
  line-height: 1;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: 0 18px 34px rgba(211, 117, 24, 0.32);
  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.cursor-lead-form__submit:hover {
  transform: translateY(-2px);
  background: linear-gradient(135deg, #bd6512, #d37518);
  box-shadow: 0 22px 44px rgba(211, 117, 24, 0.42);
}

/* Мобильная версия */
@media (max-width: 760px) {
  .cursor-lead-form {
    width: min(100% - 24px, 860px);
    padding: 24px;
    border-radius: 26px;
  }

  .cursor-lead-form__grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .cursor-lead-form__field input {
    height: 58px;
    font-size: 16px;
  }

  .cursor-lead-form__captcha {
    width: 100%;
    overflow-x: auto;
    justify-content: flex-start;
  }

  .cursor-lead-form__agree {
    padding: 14px;
    font-size: 13px;
  }

  .cursor-lead-form__submit {
    width: 100%;
    min-height: 58px;
    font-size: 15px;
  }
}


.cursor-course__referral .cursor-course__button,
.cursor-course__referral a[href="#lead-form"],
.cursor-course__referral button {
  min-width: 220px;
  min-height: 58px;
  padding: 18px 32px;
  border: 0;
  border-radius: 999px;
  background: linear-gradient(135deg, #d37518, #ffa648);
  color: #ffffff !important;
  font-size: 16px;
  font-weight: 950;
  line-height: 1;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  box-shadow: 0 18px 34px rgba(211, 117, 24, 0.34);
  cursor: pointer;
}

.cursor-course__referral .cursor-course__button:hover,
.cursor-course__referral a[href="#lead-form"]:hover,
.cursor-course__referral button:hover {
  transform: translateY(-2px);
  background: linear-gradient(135deg, #bd6512, #d37518);
  box-shadow: 0 22px 44px rgba(211, 117, 24, 0.44);
}

.swiper {
  position: relative;
  overflow: hidden;
  list-style: none;
  z-index: 1;
}

.swiper-wrapper {
  position: relative;
  display: flex;
  width: 100%;
  height: 100%;
  box-sizing: content-box;
  transition-property: transform;
}

.swiper-slide {
  flex-shrink: 0;
  width: 100%;
  height: auto;
  position: relative;
  transition-property: transform;
}

.swiper-button-prev,
.swiper-button-next {
  position: absolute;
  z-index: 10;
}

.reviews__swiper {
  position: relative;
  overflow: hidden;
}

.reviews__item.swiper-slide {
  max-width: none;
  height: auto;
}